require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "admission fence" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # While fenced, Timekeeping refuses every entry write at every generation with stale_generation, including for a company it has never seen
  it "while fenced refuses an existing company's write with an empty, malformed, admitted or next generation header and writes nothing" do
    Timekeeping::Admission.ensure_initial!
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    token = timekeeping_arrange.token_for(owner)
    entry_id = timekeeping_arrange.entry(company:, user: owner, project: timekeeping_arrange.project(company:))
    expect(Entry.find(entry_id).note).to eq("Design review")
    before = entry_write_counts
    expect(before[:entries]).to eq(1)

    Timekeeping::Admission.fence!(lock_timeout: 1)

    [nil, "abc", 1, 2].each do |generation|
      patch = build_entry_command(:update, token:, entry_id:, generation:, body: { "note" => "Edited" })
      outcome = described_class.new.call(patch)

      expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }])
      expect(entry_write_counts).to eq(before)
    end
    expect(Entry.find(entry_id).note).to eq("Design review")
    expect(Timekeeping::Admission.current.generation).to be_nil
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "admission fence for an unseen company" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # While fenced, Timekeeping refuses every entry write at every generation with stale_generation, including for a company it has never seen
  # The fence stays in place until a later admission
  it "a create for a never seen company refused while fenced stores no receipt, so the same key is written after re-admission" do
    Timekeeping::Admission.ensure_initial!
    Timekeeping::Admission.fence!(lock_timeout: 1)
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    project = timekeeping_arrange.project(company:)
    token = timekeeping_arrange.token_for(owner)
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 30.0, "note" => "Unseen",
             "source" => "manual", "source_metadata" => {} }
    key = SecureRandom.uuid
    expect(Entry.where(company_id: company).count).to eq(0)
    before = entry_write_counts

    refused = described_class.new.call(build_entry_command(:create, token:, key:, generation: 1, body:))
    retried_while_fenced = described_class.new.call(build_entry_command(:create, token:, key:, generation: 1, body:))

    expect([refused.status, JSON.parse(refused.body)]).to eq([409, { "reason" => "stale_generation" }])
    expect([retried_while_fenced.status, JSON.parse(retried_while_fenced.body)]).to eq([409, { "reason" => "stale_generation" }])
    expect(entry_write_counts).to eq(before)
    expect(Timekeeping::Admission.current.generation).to be_nil

    Timekeeping::Admission.admit!(generation: 1)
    admitted = described_class.new.call(build_entry_command(:create, token:, key:, generation: 1, body:))

    expect(admitted.status).to eq(201)
    expect(Entry.where(company_id: company).count).to eq(1)
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "re-admission at one generation" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # After re-admission at a generation, only that generation is accepted
  it "after admit at 4 a write carrying a higher generation 5 is refused like one carrying 3" do
    Timekeeping::Admission.ensure_initial!
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    token = timekeeping_arrange.token_for(owner)
    entry_id = timekeeping_arrange.entry(company:, user: owner, project: timekeeping_arrange.project(company:))
    Timekeeping::Admission.fence!(lock_timeout: 1)
    Timekeeping::Admission.admit!(generation: 4)
    before = entry_write_counts

    [3, 5].each do |generation|
      outcome = described_class.new.call(
        build_entry_command(:update, token:, entry_id:, generation:, body: { "note" => "Edited at #{generation}" })
      )
      expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }])
      expect(entry_write_counts).to eq(before)
    end

    admitted = described_class.new.call(
      build_entry_command(:update, token:, entry_id:, generation: 4, body: { "note" => "Edited at 4" })
    )
    expect(admitted.status).to eq(200)
    expect(OutboxSnapshot.where(id: entry_id).pluck(:generation)).to eq([4])
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "missing admission row" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # A lost admission row must never read as admitted at generation 1: that lazy seed is how an
  # unseen company's first write slipped past a fence before this change.
  it "with the admission row missing a write at generation 1 is refused and the row is not recreated" do
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    token = timekeeping_arrange.token_for(owner)
    entry_id = timekeeping_arrange.entry(company:, user: owner, project: timekeeping_arrange.project(company:))
    Timekeeping::Admission.delete_all
    before = entry_write_counts

    outcome = described_class.new.call(
      build_entry_command(:update, token:, entry_id:, generation: 1, body: { "note" => "Edited" })
    )

    expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }])
    expect(entry_write_counts).to eq(before)
    expect(Timekeeping::Admission.count).to eq(0)
    expect { Timekeeping::Admission.current }.to raise_error(ActiveRecord::RecordNotFound)
  ensure
    Timekeeping::Admission.ensure_initial!
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "after re-admitting twice" do
  include_context "timekeeping entry writes"

  # "After re-admission at a generation, only that generation is accepted"
  it "a second admission at 6 after one at 4 refuses writes carrying 4 and accepts only 6" do
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    token = timekeeping_arrange.token_for(owner)
    entry_id = timekeeping_arrange.entry(company:, user: owner, project: timekeeping_arrange.project(company:))

    Timekeeping::Admission.fence!(lock_timeout: 1)
    Timekeeping::Admission.admit!(generation: 4)
    Timekeeping::Admission.fence!(lock_timeout: 1)
    Timekeeping::Admission.admit!(generation: 6)
    before = entry_write_counts

    stale = described_class.new.call(
      build_entry_command(:update, token:, entry_id:, generation: 4, body: { "note" => "Stale" })
    )

    expect([stale.status, JSON.parse(stale.body)]).to eq([409, { "reason" => "stale_generation" }])
    expect(entry_write_counts).to eq(before)
    expect(Timekeeping::Admission.current.generation).to eq(6)

    current = described_class.new.call(
      build_entry_command(:update, token:, entry_id:, generation: 6, body: { "note" => "Current" })
    )

    expect(current.status).to eq(200)
    expect(Entry.find(entry_id).note).to eq("Current")
